public boolean isValid(String s) {
 Stack<Character> stack = new Stack<>();
 for (int i = 0; i < s.length(); i++) {
 char c = s.charAt(i);
 if (c == '(' || c == '{' || c == '[') {
 stack.push(c);
 } else if (c == ')') {
 if (stack.isEmpty() || stack.pop() != '(')
 return false;
 } else if (c == '}') {
 if (stack.isEmpty() || stack.pop() != '{')
 return false;
 } else if (c == ']') {
 if (stack.isEmpty() || stack.pop() != '[')
 return false;
 }
 }
 return stack.isEmpty();
}

public boolean isValid(String s) {
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (c == '(')
            stack.push(c);
        else if (c == ')') {
            if (stack.isEmpty()) return false;
            stack.pop();
        }
    }
    return stack.isEmpty();
}

